class Solution {
public:
    int findMinMoves(vector<int>& machines) {
        int total = 0;
        for (int m : machines) total += m;
        int n = machines.size();
        if (total % n != 0) return -1;

        int avg = total / n;
        int ans = 0, balance = 0;

        for (int m : machines) {
            int diff = m - avg;
            balance += diff;
            ans = max({ans, abs(balance), diff});
        }
        return ans;
    }
};

class Solution {
    public int findMinMoves(int[] machines) {
        int total = 0;
        for (int m : machines) total += m;
        int n = machines.length;
        if (total % n != 0) return -1;

        int avg = total / n;
        int ans = 0;
        int balance = 0;

        for (int m : machines) {
            int diff = m - avg;
            balance += diff;
            ans = Math.max(ans, Math.max(Math.abs(balance), diff));
        }
        return ans;
    }
}

/**
 * @param {number[]} machines
 * @return {number}
 */
var findMinMoves = function(machines) {
    const total = machines.reduce((acc, m) => acc + m, 0);
    const n = machines.length;
    if (total % n !== 0) return -1;

    const avg = Math.floor(total / n);
    let ans = 0;
    let balance = 0;

    for (const m of machines) {
        const diff = m - avg;
        balance += diff;
        ans = Math.max(ans, Math.abs(balance), diff);
    }
    return ans;
};
